/**
 * Recurssive footer credit, for our own React projects (React 19+).
 *
 * GENERATED from recurssive-credit.html (the copy-paste snippet for non-React
 * sites) by build.mjs. Edit the snippet, then run `node build.mjs`.
 * Do not edit this file by hand.
 *
 *   <RecurssiveCredit />                    gradient name (default, our projects)
 *   <RecurssiveCredit variant="plain" />    plain line (client sites, rel="nofollow")
 *   <RecurssiveCredit tone="dark" />        on a dark footer
 *
 * The <style> uses React 19 stylesheet hoisting (href + precedence), so it is
 * emitted once in <head> however many credits render, and it works in Server
 * Components with no CSS import.
 */

const CSS = ".rcsv-credit.rcsv-credit{display:inline-flex;align-items:center;gap:.45em;color:inherit;font:inherit;line-height:1;text-decoration:none;white-space:nowrap;background:none;border:0;padding:0;margin:0;box-shadow:none}\n.rcsv-credit.rcsv-credit svg{display:block;height:1em;width:auto;max-width:none;margin:0;flex:none;overflow:visible}\n.rcsv-credit.rcsv-credit .rcsv-credit__name{font-weight:600}\n.rcsv-credit{opacity:var(--rcsv-dim,.75);transition:opacity .2s}\n.rcsv-credit:hover,.rcsv-credit:focus-visible{opacity:1}\n.rcsv-credit:focus-visible{outline:2px solid #A59BFF;outline-offset:3px;border-radius:3px}\n.rcsv-credit svg{fill:currentColor;transition:fill .2s,transform .3s}\n.rcsv-credit:hover svg,.rcsv-credit:focus-visible svg{fill:#4813D0}\n.rcsv-credit--dark:hover svg,.rcsv-credit--dark:focus-visible svg{fill:#A59BFF}\n.rcsv-credit--brand{opacity:var(--rcsv-dim,1)}\n.rcsv-credit--brand svg{fill:#4813D0}\n.rcsv-credit--brand .rcsv-credit__name{background:linear-gradient(90deg,#4813D0,#6A4BE6);-webkit-background-clip:text;background-clip:text;color:transparent}\n.rcsv-credit--brand.rcsv-credit--dark svg{fill:#A59BFF}\n.rcsv-credit--brand.rcsv-credit--dark .rcsv-credit__name{background-image:linear-gradient(90deg,#A59BFF,#D9D4FF)}\n.rcsv-credit--brand:hover svg,.rcsv-credit--brand:focus-visible svg{transform:rotate(-8deg) scale(1.1)}\n@media (prefers-reduced-motion:reduce){.rcsv-credit,.rcsv-credit svg{transition:none}.rcsv-credit--brand:hover svg,.rcsv-credit--brand:focus-visible svg{transform:none}}\n@media (forced-colors:active){.rcsv-credit--brand .rcsv-credit__name{background:none;color:LinkText}.rcsv-credit svg{fill:currentColor}}"

const PATHS = [
  "M58.06 78.07C51.22 65.68 44.39 52.96 37.58 41.08C37.07 40.22 37.07 39.07 37.58 38.21C44.37 26.32 51.22 13.6 58.06 1.22C58.96 -0.41 60.96 -0.41 61.85 1.22C68.7 13.61 75.53 26.34 82.34 38.21C82.85 39.07 82.85 40.22 82.34 41.08C75.55 52.97 68.7 65.69 61.85 78.07C60.96 79.7 58.96 79.7 58.06 78.07Z",
  "M32.33 69.35C28.48 68.83 24.64 68.2 20.83 67.48C19.9 67.3 19.15 66.16 19.15 64.97V14.29C19.15 13.09 19.9 11.97 20.83 11.78C24.64 11.05 28.48 10.43 32.33 9.91C33.28 9.79 34.03 10.74 34.05 12.06V67.2C34.05 68.52 33.28 69.47 32.33 69.35Z",
  "M7.45 21.38C11.58 20.45 14.97 28.69 14.97 39.63C14.97 50.57 11.58 58.81 7.45 57.87C3.32 56.92 0 48.68 0 39.63C0 30.58 3.32 22.34 7.45 21.38Z",
  "M87.6 9.91C91.46 10.43 95.3 11.05 99.1 11.78C100.04 11.95 100.79 13.09 100.79 14.29V64.99C100.79 66.18 100.04 67.3 99.1 67.49C95.3 68.22 91.46 68.85 87.6 69.36C86.66 69.49 85.89 68.53 85.89 67.22V12.06C85.89 10.74 86.66 9.79 87.6 9.91Z",
  "M119.94 39.63C119.94 48.68 116.62 56.92 112.49 57.87C108.35 58.81 104.97 50.57 104.97 39.63C104.97 28.69 108.35 20.45 112.49 21.38C116.62 22.34 119.94 30.58 119.94 39.63Z"
] as const

export function RecurssiveCredit({
  variant = 'brand',
  tone = 'light',
  href = 'https://recurssive.com',
  className = '',
}: {
  variant?: 'plain' | 'brand'
  tone?: 'light' | 'dark'
  href?: string
  className?: string
}) {
  const classes = [
    'rcsv-credit',
    variant === 'brand' && 'rcsv-credit--brand',
    tone === 'dark' && 'rcsv-credit--dark',
    className,
  ]
    .filter(Boolean)
    .join(' ')

  return (
    <>
      <style href="rcsv-credit" precedence="low">
        {CSS}
      </style>
      <a
        className={classes}
        href={href}
        target="_blank"
        // Client sites get nofollow (see the snippet's comment); our own don't.
        rel={variant === 'plain' ? 'noopener nofollow' : 'noopener'}
      >
        <svg viewBox="0 0 120 80" aria-hidden="true" focusable="false">
          {PATHS.map((d) => (
            <path key={d} d={d} />
          ))}
        </svg>
        <span>
          Developed and designed by <span className="rcsv-credit__name">Recurssive</span>
        </span>
      </a>
    </>
  )
}
